const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = 'SkillClaw Research';
pres.title = 'SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems';

// ─── Color Palette (Deep Navy / Cyan / Violet) ────
const BG      = "0F172A";
const CARD    = "1E293B";
const CARD_L  = "273549";
const BORDER  = "334155";
const ACCENT  = "06B6D4";
const ACCENT2 = "8B5CF6";
const TXT     = "F1F5F9";
const TXT2    = "94A3B8";
const GREEN   = "10B981";
const RED     = "EF4444";
const AMBER   = "F59E0B";
const W       = "FFFFFF";

const mkShadow = () => ({ type: "outer", color: "000000", blur: 4, offset: 2, angle: 135, opacity: 0.15 });

// Figure path
const figPath = path.resolve("/app/benchmark/assets/figure_1.jpg");

// ═══════════════════════════════════════════════════
// SLIDE 1: TITLE
// ═══════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: BG };

  // Top accent bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.05, fill: { color: ACCENT } });

  // Left side: title text
  s.addText("SkillClaw", {
    x: 0.7, y: 1.0, w: 5.0, h: 0.85,
    fontSize: 42, fontFace: "Georgia", color: W, bold: true, margin: 0
  });
  s.addText("Collective Skill Evolution for\nMulti-User LLM Agent Ecosystems", {
    x: 0.7, y: 1.9, w: 5.0, h: 0.9,
    fontSize: 20, fontFace: "Calibri", color: ACCENT, margin: 0, lineSpacingMultiple: 1.2
  });
  s.addText("Let Skills Evolve Collectively with Agentic Evolver", {
    x: 0.7, y: 3.0, w: 5.0, h: 0.35,
    fontSize: 13, fontFace: "Calibri", color: TXT2, italic: true, margin: 0
  });

  // Source
  s.addText("arxiv.org/abs/2604.08377", {
    x: 0.7, y: 4.8, w: 4, h: 0.3,
    fontSize: 11, fontFace: "Calibri", color: TXT2, margin: 0
  });

  // Right side: figure_1.jpg hero image
  if (fs.existsSync(figPath)) {
    s.addImage({
      path: figPath,
      x: 5.5, y: 0.7, w: 4.2, h: 4.2,
      sizing: { type: "contain", w: 4.2, h: 4.2 },
      transparency: 8
    });
  }

  // Bottom accent bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.58, w: 10, h: 0.045, fill: { color: ACCENT } });
}

// ═══════════════════════════════════════════════════
// SLIDE 2: PROBLEM — STATIC SKILLS
// ═══════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: BG };

  s.addText("Agent Skills Remain Static After Deployment", {
    x: 0.6, y: 0.3, w: 8.8, h: 0.65,
    fontSize: 26, fontFace: "Georgia", color: W, bold: true, margin: 0
  });
  s.addText("Users Rediscover Solutions Independently", {
    x: 0.6, y: 0.9, w: 8.8, h: 0.35,
    fontSize: 15, fontFace: "Calibri", color: ACCENT, margin: 0
  });

  // Left card: Static
  s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 1.55, w: 4.15, h: 3.0, fill: { color: CARD }, shadow: mkShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 1.55, w: 0.06, h: 3.0, fill: { color: RED } });
  s.addText("Current: Static Skills", {
    x: 0.85, y: 1.7, w: 3.7, h: 0.4,
    fontSize: 16, fontFace: "Georgia", color: RED, bold: true, margin: 0
  });
  s.addText([
    { text: "Skills manually installed from a hub", options: { bullet: true, breakLine: true, fontSize: 12, color: TXT2 } },
    { text: "Never updated from runtime experience", options: { bullet: true, breakLine: true, fontSize: 12, color: TXT2 } },
    { text: "Failures rediscovered across users", options: { bullet: true, breakLine: true, fontSize: 12, color: TXT2 } },
    { text: "No system-level knowledge accumulation", options: { bullet: true, breakLine: true, fontSize: 12, color: TXT2 } },
    { text: "Memory methods tied to specific instances", options: { bullet: true, fontSize: 12, color: TXT2 } }
  ], { x: 0.85, y: 2.2, w: 3.7, h: 2.1, fontFace: "Calibri", valign: "top", paraSpaceAfter: 6 });

  // Right card: Evolving
  s.addShape(pres.shapes.RECTANGLE, { x: 5.25, y: 1.55, w: 4.15, h: 3.0, fill: { color: CARD }, shadow: mkShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 5.25, y: 1.55, w: 0.06, h: 3.0, fill: { color: GREEN } });
  s.addText("Needed: Evolving Skills", {
    x: 5.5, y: 1.7, w: 3.7, h: 0.4,
    fontSize: 16, fontFace: "Georgia", color: GREEN, bold: true, margin: 0
  });
  s.addText([
    { text: "Skills improve from real-world usage", options: { bullet: true, breakLine: true, fontSize: 12, color: TXT2 } },
    { text: "Cross-user evidence drives updates", options: { bullet: true, breakLine: true, fontSize: 12, color: TXT2 } },
    { text: "Solutions persist beyond sessions", options: { bullet: true, breakLine: true, fontSize: 12, color: TXT2 } },
    { text: "Shared knowledge accumulates", options: { bullet: true, breakLine: true, fontSize: 12, color: TXT2 } },
    { text: "Automatic, no manual curation", options: { bullet: true, fontSize: 12, color: TXT2 } }
  ], { x: 5.5, y: 2.2, w: 3.7, h: 2.1, fontFace: "Calibri", valign: "top", paraSpaceAfter: 6 });

  // Bottom insight bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 4.85, w: 8.8, h: 0.5, fill: { color: CARD_L } });
  s.addText("The gap: no existing method bridges static skill libraries and runtime-evolving agent capabilities", {
    x: 0.8, y: 4.85, w: 8.4, h: 0.5,
    fontSize: 11, fontFace: "Calibri", color: ACCENT, italic: true, margin: 0, valign: "middle"
  });
}

// ═══════════════════════════════════════════════════
// SLIDE 3: ARCHITECTURE OVERVIEW
// ═══════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: BG };

  s.addText("Closed-Loop Pipeline: From Multi-User Interaction to Shared Skill Evolution", {
    x: 0.5, y: 0.2, w: 9, h: 0.55,
    fontSize: 21, fontFace: "Georgia", color: W, bold: true, margin: 0
  });

  // ── Top bar: Multi-User Interaction ──
  const topBarY = 0.95;
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: topBarY, w: 9, h: 0.75, fill: { color: CARD }, shadow: mkShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: topBarY, w: 9, h: 0.04, fill: { color: ACCENT } });
  s.addText("Multi-User Interaction", {
    x: 0.5, y: topBarY + 0.05, w: 9, h: 0.35,
    fontSize: 13, fontFace: "Georgia", color: W, bold: true, align: "center", valign: "middle", margin: 0
  });
  s.addText("OpenClaw  ·  CoPaw  ·  IronClaw  ·  PicoClaw  ·  ZeroClaw  ·  NanoClaw  ·  NemoClaw", {
    x: 0.5, y: topBarY + 0.38, w: 9, h: 0.3,
    fontSize: 9.5, fontFace: "Calibri", color: TXT2, align: "center", valign: "middle", margin: 0
  });

  // Down arrow
  s.addShape(pres.shapes.LINE, { x: 5, y: topBarY + 0.75, w: 0, h: 0.25, line: { color: ACCENT, width: 1.5 } });
  s.addText("▼", { x: 4.75, y: topBarY + 0.95, w: 0.5, h: 0.25, fontSize: 11, color: ACCENT, align: "center", valign: "middle", margin: 0 });

  // ── Four stage boxes ──
  const stageY = 1.75;
  const stageW = 1.9;
  const stageH = 1.7;
  const gap = 0.3;
  const totalW = 4 * stageW + 3 * gap;
  const startX = (10 - totalW) / 2;

  const stages = [
    { label: "EVIDENCE", color: ACCENT, num: "1", desc: "Analyze trajectories to identify behavioral patterns across sessions" },
    { label: "ATTRIBUTION", color: ACCENT2, num: "2", desc: "Diagnose root causes of failures and successes in skill execution" },
    { label: "EVOLUTION", color: GREEN, num: "3", desc: "Propose skill mutations — refine existing skills or create new ones" },
    { label: "DISTRIBUTION", color: AMBER, num: "4", desc: "Verify updates, merge into shared repository, sync to all agents" }
  ];

  stages.forEach((stage, i) => {
    const x = startX + i * (stageW + gap);
    s.addShape(pres.shapes.RECTANGLE, { x, y: stageY, w: stageW, h: stageH, fill: { color: CARD }, shadow: mkShadow() });
    s.addShape(pres.shapes.RECTANGLE, { x, y: stageY, w: stageW, h: 0.04, fill: { color: stage.color } });

    // Number circle
    s.addShape(pres.shapes.OVAL, {
      x: x + stageW / 2 - 0.17, y: stageY + 0.15, w: 0.34, h: 0.34,
      fill: { color: stage.color }
    });
    s.addText(stage.num, {
      x: x + stageW / 2 - 0.17, y: stageY + 0.15, w: 0.34, h: 0.34,
      fontSize: 13, fontFace: "Georgia", color: BG, bold: true, align: "center", valign: "middle", margin: 0
    });

    // Label
    s.addText(stage.label, {
      x, y: stageY + 0.55, w: stageW, h: 0.3,
      fontSize: 10.5, fontFace: "Georgia", color: stage.color, bold: true, align: "center", valign: "middle", margin: 0
    });

    // Description
    s.addText(stage.desc, {
      x: x + 0.1, y: stageY + 0.9, w: stageW - 0.2, h: 0.7,
      fontSize: 8.5, fontFace: "Calibri", color: TXT2, align: "center", valign: "top", margin: 0, lineSpacingMultiple: 1.3
    });

    // Arrow between stages
    if (i < 3) {
      s.addText("→", {
        x: x + stageW, y: stageY + 0.6, w: gap, h: 0.35,
        fontSize: 16, color: TXT2, align: "center", valign: "middle", margin: 0
      });
    }
  });

  // ── Return arrow (dashed) ──
  const retY = stageY + stageH + 0.15;
  const leftX = startX + 0.4;
  const rightX = startX + totalW - 0.4;
  // Horizontal dashed line
  s.addShape(pres.shapes.LINE, { x: leftX, y: retY + 0.25, w: rightX - leftX, h: 0, line: { color: ACCENT, width: 1.2, dashType: "dash" } });
  // Left vertical stub up
  s.addShape(pres.shapes.LINE, { x: leftX, y: retY, w: 0, h: 0.25, line: { color: ACCENT, width: 1.2, dashType: "dash" } });
  // Right vertical stub up
  s.addShape(pres.shapes.LINE, { x: rightX, y: retY, w: 0, h: 0.25, line: { color: ACCENT, width: 1.2, dashType: "dash" } });
  // Return label
  s.addText("Skill Synchronization — Closed Loop", {
    x: 2.5, y: retY + 0.35, w: 5, h: 0.28,
    fontSize: 9.5, fontFace: "Calibri", color: ACCENT, align: "center", valign: "middle", margin: 0, italic: true
  });

  // Bracket label above stages
  s.addText("Agentic Evolver", {
    x: startX, y: stageY - 0.3, w: totalW, h: 0.25,
    fontSize: 11, fontFace: "Georgia", color: ACCENT, bold: true, align: "center", valign: "middle", margin: 0
  });
}

// ═══════════════════════════════════════════════════
// SLIDE 4: AGENTIC EVOLVER PIPELINE
// ═══════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: BG };

  s.addText("Agentic Evolver: Evidence → Attribution → Evolution", {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 24, fontFace: "Georgia", color: W, bold: true, margin: 0
  });
  s.addText("Three stages of open-ended agent reasoning — not predefined rules", {
    x: 0.5, y: 0.75, w: 9, h: 0.3,
    fontSize: 13, fontFace: "Calibri", color: ACCENT, italic: true, margin: 0
  });

  // Three vertical cards
  const cards = [
    {
      stage: "Stage 1: EVIDENCE", color: ACCENT,
      title: "Analyze Trajectories",
      bullets: [
        "Collect structured session trajectories from multi-user interactions",
        "Preserve full action–feedback causal chains",
        "Group trajectories by referenced skills",
        "Identify behavioral patterns across sessions"
      ]
    },
    {
      stage: "Stage 2: ATTRIBUTION", color: ACCENT2,
      title: "Diagnose Root Causes",
      bullets: [
        "Determine why a skill succeeded or failed in a given context",
        "Distinguish generalizable patterns from idiosyncratic fixes",
        "Cross-reference failure modes across different users",
        "Isolate actionable improvement signals"
      ]
    },
    {
      stage: "Stage 3: EVOLUTION", color: GREEN,
      title: "Propose Skill Mutations",
      bullets: [
        "Refine existing skills based on attributed causes",
        "Create new skills when gaps are identified",
        "Generate candidate skills for verification",
        "Conservative: only verified mutations are merged"
      ]
    }
  ];

  const cardW = 2.8;
  const cardH = 3.7;
  const gap = 0.35;
  const totalW = 3 * cardW + 2 * gap;
  const startX = (10 - totalW) / 2;
  const cardY = 1.25;

  cards.forEach((c, i) => {
    const x = startX + i * (cardW + gap);
    s.addShape(pres.shapes.RECTANGLE, { x, y: cardY, w: cardW, h: cardH, fill: { color: CARD }, shadow: mkShadow() });
    s.addShape(pres.shapes.RECTANGLE, { x, y: cardY, w: cardW, h: 0.05, fill: { color: c.color } });

    // Stage label
    s.addText(c.stage, {
      x: x + 0.15, y: cardY + 0.15, w: cardW - 0.3, h: 0.3,
      fontSize: 10, fontFace: "Georgia", color: c.color, bold: true, margin: 0
    });
    // Title
    s.addText(c.title, {
      x: x + 0.15, y: cardY + 0.45, w: cardW - 0.3, h: 0.35,
      fontSize: 14, fontFace: "Georgia", color: W, bold: true, margin: 0
    });
    // Bullets
    const bulletItems = c.bullets.map((b, idx) => ({
      text: b,
      options: {
        bullet: true,
        breakLine: idx < c.bullets.length - 1,
        fontSize: 10,
        color: TXT2
      }
    }));
    s.addText(bulletItems, {
      x: x + 0.15, y: cardY + 0.9, w: cardW - 0.3, h: 2.6,
      fontFace: "Calibri", valign: "top", paraSpaceAfter: 5
    });

    // Arrow between cards
    if (i < 2) {
      s.addText("→", {
        x: x + cardW, y: cardY + 1.5, w: gap, h: 0.4,
        fontSize: 20, color: c.color, align: "center", valign: "middle", margin: 0
      });
    }
  });
}

// ═══════════════════════════════════════════════════
// SLIDE 5: MULTI-USER AGGREGATION
// ═══════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: BG };

  s.addText("Cross-User Trajectory Aggregation Exposes Skill Behavioral Boundaries", {
    x: 0.5, y: 0.2, w: 9, h: 0.55,
    fontSize: 21, fontFace: "Georgia", color: W, bold: true, margin: 0
  });

  // Left column: visual showing aggregation
  const leftX = 0.5;
  const leftW = 4.8;

  // Agent boxes flowing in
  const agents = ["OpenClaw", "CoPaw", "IronClaw", "PicoClaw", "ZeroClaw", "NanoClaw", "NemoClaw"];
  const agentY = 1.1;
  agents.forEach((name, i) => {
    const row = Math.floor(i / 4);
    const col = i % 4;
    const bx = leftX + 0.1 + col * 1.15;
    const by = agentY + row * 0.65;
    s.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: by, w: 1.05, h: 0.5,
      fill: { color: CARD_L },
      line: { color: BORDER, width: 0.5 }
    });
    s.addText(name, {
      x: bx, y: by, w: 1.05, h: 0.5,
      fontSize: 8.5, fontFace: "Calibri", color: TXT2, align: "center", valign: "middle", margin: 0
    });
  });

  // Down arrows to aggregation
  s.addText("▼  ▼  ▼  ▼", {
    x: leftX + 0.1, y: agentY + 1.35, w: leftW - 0.2, h: 0.25,
    fontSize: 10, color: ACCENT, align: "center", valign: "middle", margin: 0
  });

  // Aggregation box
  const aggY = agentY + 1.7;
  s.addShape(pres.shapes.RECTANGLE, {
    x: leftX + 0.3, y: aggY, w: leftW - 0.6, h: 0.6,
    fill: { color: ACCENT, transparency: 85 },
    line: { color: ACCENT, width: 1 }
  });
  s.addText("Session Collection & Grouping by Skill", {
    x: leftX + 0.3, y: aggY, w: leftW - 0.6, h: 0.6,
    fontSize: 11, fontFace: "Georgia", color: ACCENT, bold: true, align: "center", valign: "middle", margin: 0
  });

  // Down arrow
  s.addText("▼", {
    x: leftX + 1.5, y: aggY + 0.6, w: 1.5, h: 0.25,
    fontSize: 12, color: ACCENT, align: "center", valign: "middle", margin: 0
  });

  // Shared evidence base
  const evY = aggY + 0.9;
  s.addShape(pres.shapes.RECTANGLE, {
    x: leftX + 0.3, y: evY, w: leftW - 0.6, h: 0.55,
    fill: { color: CARD },
    line: { color: GREEN, width: 1 }
  });
  s.addText("Shared Evidence Base", {
    x: leftX + 0.3, y: evY, w: leftW - 0.6, h: 0.55,
    fontSize: 11, fontFace: "Georgia", color: GREEN, bold: true, align: "center", valign: "middle", margin: 0
  });

  // Right column: key insights
  const rightX = 5.7;
  const rightW = 3.8;

  s.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 1.1, w: rightW, h: 3.4,
    fill: { color: CARD }, shadow: mkShadow()
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 1.1, w: 0.06, h: 3.4, fill: { color: ACCENT2 }
  });

  s.addText("Why Aggregation Matters", {
    x: rightX + 0.2, y: 1.2, w: rightW - 0.4, h: 0.35,
    fontSize: 14, fontFace: "Georgia", color: ACCENT2, bold: true, margin: 0
  });

  s.addText([
    {
      text: "Complementary signals",
      options: { bold: true, breakLine: true, fontSize: 11, color: TXT }
    },
    {
      text: "Different users exercising the same skill under diverse contexts produce complementary views — revealing both success conditions and failure modes.",
      options: { breakLine: true, fontSize: 10, color: TXT2, paraSpaceAfter: 8 }
    },
    {
      text: "Single-user insufficiency",
      options: { bold: true, breakLine: true, fontSize: 11, color: TXT }
    },
    {
      text: "A single user rarely generates enough signal to separate a generalizable improvement from an idiosyncratic fix.",
      options: { breakLine: true, fontSize: 10, color: TXT2, paraSpaceAfter: 8 }
    },
    {
      text: "Behavioral boundary mapping",
      options: { bold: true, breakLine: true, fontSize: 11, color: TXT }
    },
    {
      text: "Cross-user aggregation maps the boundary where a skill works vs. where it breaks, enabling targeted evolution.",
      options: { fontSize: 10, color: TXT2 }
    }
  ], {
    x: rightX + 0.2, y: 1.6, w: rightW - 0.4, h: 2.7,
    fontFace: "Calibri", valign: "top"
  });
}

// ═══════════════════════════════════════════════════
// SLIDE 6: CASE STUDY — CREATIVE PIPELINE
// ═══════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: BG };

  s.addText("Case Study: Multimodal Creative Pipeline Skill", {
    x: 0.5, y: 0.2, w: 7, h: 0.5,
    fontSize: 22, fontFace: "Georgia", color: W, bold: true, margin: 0
  });
  s.addText("6 Days of Evolution Attempts — 1 of 6 Accepted", {
