  });
  s.addText("accepted", {
    x: 7.7, y: 0.6, w: 1.9, h: 0.3,
    fontSize: 10, fontFace: "Calibri", color: TXT2, align: "center", valign: "middle", margin: 0
  });

  // Table
  const headerOpts = { fill: { color: CARD_L }, color: ACCENT, bold: true, fontSize: 9, fontFace: "Calibri", align: "center", valign: "middle" };
