      { text: "Added image classification, visual generation, structured validation", options: cellOpts },
      { text: "Reject", options: rejectOpts },
      { text: "Keep current best pool", options: cellOpts }
    ],
    [
      { text: "5", options: { ...cellOpts, align: "center" } },
      { text: "...(impr.) + validate-required-input-files", options: cellOpts },
      { text: "Creative pipeline + per-file fail-fast validation", options: cellOpts },
      { text: "Reject", options: rejectOpts },
