      { text: "Extended PDF-to-poster / document-to-visual paths", options: cellOpts },
      { text: "Reject", options: rejectOpts },
      { text: "Not admitted to next cycle", options: cellOpts }
    ]
  ];

  s.addTable(tableData, {
    x: 0.4, y: 1.1, w: 9.2,
    colW: [0.4, 2.2, 3.0, 0.7, 2.9],
