  const cellOpts = { fill: { color: CARD }, color: TXT2, fontSize: 8.5, fontFace: "Calibri", valign: "middle" };
  const acceptOpts = { ...cellOpts, color: GREEN, bold: true, align: "center" };
  const rejectOpts = { ...cellOpts, color: RED, bold: true, align: "center" };

  const tableData = [
    [
      { text: "Day", options: headerOpts },
