      { text: "Next-Day Action", options: headerOpts }
    ],
    [
      { text: "1", options: { ...cellOpts, align: "center" } },
      { text: "git-push-with-auth-fallback", options: cellOpts },
      { text: "Safe fallback instead of blocking on push failure", options: cellOpts },
      { text: "Accept", options: acceptOpts },
      { text: "Add to Safety best pool", options: cellOpts }
    ],
    [
      { text: "2", options: { ...cellOpts, align: "center" } },
      { text: "git-push-with-auth-fallback", options: cellOpts },
      { text: "Unified patch/bundle filenames, reduced inconsistency", options: cellOpts },
      { text: "Accept", options: acceptOpts },
      { text: "Keep updated best pool", options: cellOpts }
    ],
    [
      { text: "3", options: { ...cellOpts, align: "center" } },
      { text: "... + git-clone-to-directory", options: cellOpts },
      { text: "Auth-alternative paths & secrets audit; fixed subshell pitfalls", options: cellOpts },
      { text: "Accept", options: acceptOpts },
      { text: "Keep current best pool", options: cellOpts }
    ],
    [
      { text: "4", options: { ...cellOpts, align: "center" } },
      { text: "(none)", options: { ...cellOpts, color: TXT2, italic: true } },
