    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 23, fontFace: "Georgia", color: W, bold: true, margin: 0
  });

  // Three cards
  const cards = [
    {
      num: "1", color: ACCENT,
      title: "Collective Evolution",
      desc: "Knowledge from individual interactions contributes to a shared, continuously improving skill ecosystem. Each user’s experience benefits all other users."
    },
    {
      num: "2", color: ACCENT2,
      title: "Fully Automatic",
      desc: "Skill evolution is driven by runtime interaction without manual curation or explicit user intervention. No human in the loop required."
    },
    {
      num: "3", color: GREEN,
      title: "Agentic Evolution Paradigm",
      desc: "Skill updates are produced through open-ended reasoning over evidence rather than predefined update rules. The evolver adapts its strategy to the data."
    }
  ];

  const cardW = 2.8;
  const cardH = 2.7;
  const gap = 0.35;
  const totalW = 3 * cardW + 2 * gap;
  const startX = (10 - totalW) / 2;
  const cardY = 1.1;

  cards.forEach((c, i) => {
    const x = startX + i * (cardW + gap);
    s.addShape(pres.shapes.RECTANGLE, { x, y: cardY, w: cardW, h: cardH, fill: { color: CARD }, shadow: mkShadow() });
    s.addShape(pres.shapes.RECTANGLE, { x, y: cardY, w: cardW, h: 0.05, fill: { color: c.color } });

    // Number circle
    s.addShape(pres.shapes.OVAL, {
      x: x + 0.2, y: cardY + 0.2, w: 0.45, h: 0.45,
      fill: { color: c.color }
    });
    s.addText(c.num, {
      x: x + 0.2, y: cardY + 0.2, w: 0.45, h: 0.45,
      fontSize: 18, fontFace: "Georgia", color: BG, bold: true, align: "center", valign: "middle", margin: 0
    });

    // Title
    s.addText(c.title, {
      x: x + 0.75, y: cardY + 0.2, w: cardW - 0.95, h: 0.45,
      fontSize: 15, fontFace: "Georgia", color: c.color, bold: true, valign: "middle", margin: 0
    });

    // Description
    s.addText(c.desc, {
      x: x + 0.2, y: cardY + 0.8, w: cardW - 0.4, h: 1.7,
      fontSize: 10.5, fontFace: "Calibri", color: TXT2, valign: "top", margin: 0, lineSpacingMultiple: 1.4
    });
  });

  // Implications bar at bottom
  const impY = 4.15;
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: impY, w: 9, h: 1.15, fill: { color: CARD_L } });
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: impY, w: 9, h: 0.04, fill: { color: AMBER } });

  s.addText("Implications for Continuously Improving Agent Systems", {
    x: 0.7, y: impY + 0.1, w: 8.6, h: 0.3,
    fontSize: 12, fontFace: "Georgia", color: AMBER, bold: true, margin: 0
  });
  s.addText([
    {
      text: "SkillClaw demonstrates that agent ecosystems can self-improve by aggregating distributed interaction evidence and applying agentic reasoning to evolve shared skill repositories.",
      options: { breakLine: true, fontSize: 10, color: TXT2 }
    },
    {
      text: "Evaluated on WildClawBench with Qwen3-Max backbone, showing substantial improvements across tasks. Compatible with OpenClaw, CoPaw, IronClaw, PicoClaw, ZeroClaw, NanoClaw, and NemoClaw.",
      options: { fontSize: 10, color: TXT2 }
    }
  ], {
    x: 0.7, y: impY + 0.45, w: 8.6, h: 0.6,
    fontFace: "Calibri", valign: "top"
  });
}

// ─── Write File ────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Presentation saved to /app/output/final_deck.pptx"))
  .catch(err => console.error("Error:", err));

