  // ── Four stage boxes ──
  const stageY = 1.75;
  const stageW = 1.9;
  const stageH = 1.7;
  const gap = 0.3;
  const totalW = 4 * stageW + 3 * gap;
  const startX = (10 - totalW) / 2;

